mapper.update:
UPDATE PLAN_DAY
   SET SCHEDULE_VERSION = SCHEDULE_VERSION + 1
 WHERE PLAN_DAY_ID = #{planDayId}
   AND PLAN_ID = #{planId}
   AND SCHEDULE_VERSION = #{scheduleVersion}

